function dijkstra(start,end,time=state.time){if(start===end)return{path:[start],distance:0,physical:0};const dist={},prev={},open=new Set(Object.keys(nodes));Object.keys(nodes).forEach(k=>dist[k]=Infinity);dist[start]=0;while(open.size){let u=null;open.forEach(k=>{if(u===null||dist[k]<dist[u])u=k});if(u===null||dist[u]===Infinity)break;open.delete(u);if(u===end)break;for(const e of graph[u]){if(!open.has(e.to)||state.closed.has(edgeKey(u,e.to)))continue;const nd=dist[u]+e.d*trafficFactor(u,e.to,time);if(nd<dist[e.to]){dist[e.to]=nd;prev[e.to]=u}}}if(!Number.isFinite(dist[end]))return{path:[],distance:Infinity,physical:Infinity};const path=[];for(let u=end;u;u=prev[u]){path.unshift(u);if(u===start)break}let physical=0;for(let i=1;i<path.length;i++)physical+=Math.hypot(nodes[path[i]].x-nodes[path[i-1]].x,nodes[path[i]].y-nodes[path[i-1]].y);return{path,distance:dist[end],physical}}
