function prepareSession(startMinute=state.time,announce=true){const start=Math.max(390,Math.min(1140,Math.round(startMinute)));seed=(24681357^Math.imul(start,2654435761))>>>0;state.time=start;state.sessionStart=start;state.sessionEnd=start+60;state.running=false;state.selectedOrder=null;state.orders=[];state.quarantine=[];state.orderWave=0;state.maxOrderWaves=6;state.nextWaveMinute=start;state.flowComplete=false;state.activityStarted=false;state.metrics={energy:0,distance:0,loadedDistance:0,delivered:0,ontime:0,late:0,securityBlocked:0,securityHandled:0,securityMissed:0};state.vehicles=[makeVehicle('E-01','van','06'),makeVehicle('E-02','van','06'),makeVehicle('U-01','bot','06'),makeVehicle('U-02','bot','13'),makeVehicle('U-03','bot','06')];$('#log').innerHTML='';generateOrderWave();addLog(`已准备 ${fmtTime(start)}–${fmtTime(state.sessionEnd)} 一小时场景`);$('#playBtn').textContent='▶ 开始仿真';setSecurity();if(announce)showToast(`已生成 ${fmtTime(start)} 启动的可复现场景，${fmtTime(state.sessionEnd)} 自动结算。`);renderAll()}
