function createOrder(origin,dest,qty=1,due=35,priority='普通',id=null,category='快递'){const order={id:id||'O-'+String(state.orders.length+state.quarantine.length+1).padStart(2,'0'),origin,dest,qty,weight:+(qty*(1.2+rand()*2.3)).toFixed(1),created:state.time,due:state.time+due,priority,category,status:'pending',vehicle:null,delivered:null,suspicious:false};state.orders.push(order);return order}
function pendingOrders(){return state.orders.filter(o=>o.status==='pending')}
function activeOrders(){return state.orders.filter(o=>o.status==='pending'||o.status==='assigned')}
function overdueOrders(){return activeOrders().filter(o=>state.time>o.due)}
function outcomeRate(){const evaluated=state.metrics.delivered+overdueOrders().length;return evaluated?state.metrics.ontime/evaluated*100:null}
function routeVehicle(v,dest,stage){const route=dijkstra(v.currentNode,dest);if(!route.path.length){addLog(`${v.id} 无可用路径到达 ${nodes[dest].name}`,true);return false}v.path=route.path;v.pathIndex=1;v.stage=stage;if(route.path.length===1)handleArrival(v);return true}
function assignOrders(v,orders){if(!orders.length||v.status!=='空闲')return false;const qty=orders.reduce((s,o)=>s+o.qty,0);if(qty>v.capacity){addLog(`${v.id} 容量不足，无法装载 ${qty} 件`,true);return false}if(v.battery<16){addLog(`${v.id} 电量不足，已拒绝派单`,true);return false}orders.forEach(o=>{o.status='assigned';o.vehicle=v.id});v.mission={orders:orders.map(o=>o.id),origin:orders[0].origin,dest:orders[0].dest};v.status='前往取货';v.load=0;if(!routeVehicle(v,v.mission.origin,'pickup')){orders.forEach(o=>{o.status='pending';o.vehicle=null});v.mission=null;v.status='空闲';v.stage=null;return false}state.activityStarted=true;addLog(`${v.id} 接收 ${orders.length} 单：${nodes[v.mission.origin].name} → ${nodes[v.mission.dest].name}`);state.selectedOrder=null;renderPanels();return true}
function handleArrival(v){v.currentNode=v.path[v.path.length-1]||v.currentNode;v.x=nodes[v.currentNode].x;v.y=nodes[v.currentNode].y;v.path=[];v.pathIndex=0;if(v.stage==='pickup'){const os=v.mission.orders.map(id=>state.orders.find(o=>o.id===id));v.load=os.reduce((s,o)=>s+o.qty,0);v.status='配送中';routeVehicle(v,v.mission.dest,'delivery')}else if(v.stage==='delivery'){const os=v.mission.orders.map(id=>state.orders.find(o=>o.id===id));os.forEach(o=>{o.status='delivered';o.delivered=state.time;state.metrics.delivered++;if(state.time<=o.due)state.metrics.ontime++;else state.metrics.late++});addLog(`${v.id} 已送达 ${nodes[v.currentNode].name}，完成 ${os.length} 单`);v.mission=null;v.load=0;v.status='空闲';v.stage=null;if(v.battery<25)sendCharge(v)}else if(v.stage==='charge'){v.status=state.events.has('charger')?'等待充电':'充电中';v.stage='charging'}renderAll()}
function sendCharge(v){if(v.currentNode==='06'){v.status=state.events.has('charger')?'等待充电':'充电中';v.stage='charging'}else{v.status='返场充电';routeVehicle(v,'06','charge')}}
function updateVehicle(v,simMinutes){if(v.stage==='charging'){if(!state.events.has('charger')){v.battery=Math.min(100,v.battery+simMinutes*2.3);if(v.battery>=92){v.status='空闲';v.stage=null;addLog(`${v.id} 完成充电`)}}return}if(!v.path.length||v.pathIndex>=v.path.length)return;const targetId=v.path[v.pathIndex],target=nodes[targetId],dx=target.x-v.x,dy=target.y-v.y,dist=Math.hypot(dx,dy),edgeFrom=v.currentNode,traffic=trafficFactor(edgeFrom,targetId);const move=Math.min(dist,v.speed/traffic*simMinutes);if(dist>0){v.x+=dx/dist*move;v.y+=dy/dist*move;const km=move*MAP_KM_PER_PIXEL,loaded=v.stage==='delivery';const loadFactor=1+(v.load/v.capacity)*.22;const used=km*v.rate*loadFactor*traffic;v.energy+=used;v.distance+=km;if(loaded)v.loadedDistance+=km;v.battery=Math.max(0,v.battery-used/v.batteryKwh*100);state.metrics.energy+=used;state.metrics.distance+=km;if(loaded)state.metrics.loadedDistance+=km}if(move>=dist-.01){v.currentNode=targetId;v.x=target.x;v.y=target.y;v.pathIndex++;if(v.pathIndex>=v.path.length)handleArrival(v)}}
function autoDispatch(){const pend=pendingOrders();if(!pend.length){addLog('当前没有待派订单');showToast('没有待派订单，车辆保持空闲。');return 0}const active=state.vehicles.filter(v=>v.status!=='空闲').length,target=demandProfile(state.time).active,slots=Math.max(0,target-active),idle=state.vehicles.filter(v=>v.status==='空闲'&&v.battery>=16);if(!idle.length||!slots)return 0;let assigned=0;if(state.strategy==='batch'){const groups={};pend.forEach(o=>{const k=o.origin+'-'+o.dest;(groups[k]??=[]).push(o)});for(const group of Object.values(groups)){if(assigned>=slots)break;const candidates=idle.filter(x=>x.status==='空闲').sort((a,b)=>vehicleCost(a,group[0],state.strategy)-vehicleCost(b,group[0],state.strategy));if(!candidates.length)break;const v=candidates[0],batch=[];let quantity=0;for(const o of group){if(quantity+o.qty<=v.capacity){batch.push(o);quantity+=o.qty}}if(assignOrders(v,batch))assigned++}}else{for(const o of pend){if(assigned>=slots)break;const options=idle.filter(v=>v.status==='空闲'&&o.qty<=v.capacity);if(!options.length)break;options.sort((a,b)=>vehicleCost(a,o,state.strategy)-vehicleCost(b,o,state.strategy));if(assignOrders(options[0],[o]))assigned++}}if(assigned){state.running=true;state.activityStarted=true;$('#playBtn').textContent='Ⅱ 暂停';addLog(`自动派出${assigned}辆，当前活跃上限${target}辆`);showToast(`${period(state.time).name}：已派出${assigned}辆，建议活跃${target}辆。`)}renderAll();return assigned}
function vehicleCost(v,o,strategy){const pickup=dijkstra(v.currentNode,o.origin).distance,trip=dijkstra(o.origin,o.dest).distance;if(!Number.isFinite(pickup+trip))return Infinity;if(strategy==='nearest')return pickup+trip;const km=(pickup+trip)*MAP_KM_PER_PIXEL,energy=km*v.rate*(1+o.qty/v.capacity*.22);const typePenalty=strategy==='eco'?(v.type==='van'&&trip<270?85:0)+(v.type==='bot'&&trip>430?120:0):0;return energy*900+pickup*.3+typePenalty}
function pick(list){return list[Math.floor(rand()*list.length)]}
function weightedCategory(weights){let r=rand();for(const [key,value] of Object.entries(weights)){r-=value;if(r<=0)return key}return'market'}
function orderSpec(category){const dorms=['05B','07','08','12'],teaching=['01','14','15','16','17','18','19','20','21','24'],sports=['04','09','23','25'],parks=['02','10','11','22'];if(category==='meal')return{origin:'06',dest:pick(rand()<.72?dorms:teaching),qty:1+Math.floor(rand()*2),due:20+Math.floor(rand()*9),label:'餐饮'};if(category==='parcel')return{origin:'06',dest:pick(rand()<.62?dorms:teaching),qty:1+Math.floor(rand()*2),due:30+Math.floor(rand()*13),label:'快递'};if(category==='market')return{origin:'13',dest:pick(rand()<.58?dorms:rand()<.82?teaching:sports),qty:1+Math.floor(rand()*2),due:27+Math.floor(rand()*12),label:'商超'};if(category==='facility')return{origin:rand()<.55?'24':'05R',dest:pick([...sports,...parks]),qty:1+Math.floor(rand()*3),due:38+Math.floor(rand()*13),label:'场地运维'};let origin=pick(['05R','18','24']),dest=pick(['01','14','15','16','17','18','19','20','21','24','05R']);if(dest===origin)dest='01';return{origin,dest,qty:1,due:28+Math.floor(rand()*13),label:'行政教学'}}
function generateOrderWave(){if(state.orderWave>=state.maxOrderWaves||state.time>=1200)return 0;const profile=demandProfile(state.time),count=profile.count+(rand()>.72?1:0),waveNumber=state.orderWave+1;for(let i=0;i<count;i++){const spec=orderSpec(weightedCategory(profile.weights)),priority=rand()>.84?'紧急':'普通';createOrder(spec.origin,spec.dest,spec.qty,priority==='紧急'?Math.max(18,spec.due-8):spec.due,priority,null,spec.label)}state.orderWave=waveNumber;state.nextWaveMinute=state.sessionStart+waveNumber*10;addLog(`第${waveNumber}/${state.maxOrderWaves}轮订单已到达：新增${count}单`);if(waveNumber>1)showToast(`第${waveNumber}轮订单已进入调度队列。`);return count}
function replanMovingVehicles(){let count=0;state.vehicles.forEach(v=>{if(!v.path.length||!v.stage||v.pathIndex>=v.path.length)return;const from=v.currentNode,to=v.path[v.pathIndex],dest=v.stage==='pickup'?v.mission?.origin:v.stage==='delivery'?v.mission?.dest:'06';if(!dest)return;const candidates=[from,to].map(endpoint=>{const access=Math.hypot(v.x-nodes[endpoint].x,v.y-nodes[endpoint].y),route=dijkstra(endpoint,dest);return{endpoint,access,route,total:access+(route.distance||0)}}).filter(x=>x.route.path.length).sort((a,b)=>a.total-b.total);if(!candidates.length)return;const best=candidates[0];v.path=[best.endpoint,...best.route.path.slice(1)];v.pathIndex=0;count++;addLog(`${v.id} 保留道路进度，选择${best.endpoint===from?'掉头':'前行'}至${nodes[best.endpoint].name}后绕行`)});return count}
function canonicalOrder(o){return JSON.stringify({created:o.created,dest:o.dest,due:o.due,id:o.id,origin:o.origin,qty:o.qty})}
async function sha256(text){const data=new TextEncoder().encode(text),hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function triggerEvent(name,button){
 const active=state.events.has(name);
 state.activityStarted=true;
 if(name==='surge'&&!active){state.events.add(name);for(let i=0;i<8;i++)createOrder(i<6?'06':'13',['05B','07','08','12'][i%4],1+(i%2),22+i*2,i<2?'紧急':'普通');addLog('订单暴增：新增8条可信订单',true)}
 else if(name==='attack'&&!active){state.events.add(name);const original={id:'X-'+String(state.quarantine.length+1).padStart(2,'0'),origin:'06',dest:'12',qty:3,created:Math.round(state.time),due:Math.round(state.time+18)},originalDigest=await sha256(canonicalOrder(original)),tampered={...original,dest:'05R'},tamperedDigest=await sha256(canonicalOrder(tampered));const bad={...original,tamperedDest:tampered.dest,originalDigest,tamperedDigest,status:'quarantined',suspicious:true,risk:originalDigest===tamperedDigest?0:92,reason:'规范化JSON的SHA-256摘要不一致'};state.quarantine.push(bad);state.metrics.securityBlocked++;addLog('摘要校验失败：异常订单已自动隔离，等待人工复核',true);setSecurity(bad)}
 else{
  active?state.events.delete(name):state.events.add(name);
  if(name==='closure'){const k=edgeKey('06','07');active?state.closed.delete(k):state.closed.add(k);const count=replanMovingVehicles();addLog(active?'06-07道路恢复通行':`06-07道路封闭，已为${count}辆在途车辆重算路线`,!active)}
  if(name==='flood'){const k=edgeKey('23','24');active?state.closed.delete(k):state.closed.add(k);const count=replanMovingVehicles();addLog(active?'滨水道路积水消退，23-24恢复通行':`水岸突发积水，23-24封闭，已为${count}辆在途车辆重算路线`,!active)}
  if(name==='charger')addLog(active?'充电设施恢复':'06充电设施故障，低电量车辆进入等待',!active)
 }
 button.classList.toggle('active',state.events.has(name));$('#eventState').textContent=state.events.size?`${state.events.size}项事件`:'正常';renderAll()
}
function reviewAttack(){const bad=state.quarantine.find(o=>o.status==='quarantined');if(!bad)return;bad.status='recovered';createOrder(bad.origin,bad.dest,bad.qty,24,'紧急','R-'+bad.id.slice(2));state.metrics.securityHandled++;state.events.delete('attack');$$('[data-event="attack"]').forEach(b=>b.classList.remove('active'));addLog(`人工复核完成：恢复原始可信目的地 ${nodes[bad.dest].name}`);setSecurity();renderAll()}
function setSecurity(bad=null){const q=bad||state.quarantine.find(o=>o.status==='quarantined');$('#reviewAttack').disabled=!q;$('#securityStatus').textContent=q?`已隔离 · 风险 ${q.risk}/100`:state.metrics.securityHandled?'已复核恢复':'无异常';$('#securityDetail').textContent=q?`${q.id}：${q.reason}。原摘要 ${q.originalDigest.slice(0,12)}…；篡改后 ${q.tamperedDigest.slice(0,12)}…。字段 dest：${nodes[q.dest].name} → ${nodes[q.tamperedDest].name}，已自动拦截，尚未计为人工处置。`:'订单先规范化为JSON并计算SHA-256摘要；只有完成拦截或人工复核后才计入安全处置。';const spans=$$('#securityFlow span');spans.forEach(s=>s.className='');if(q){spans[1].className='alert';spans[2].className='alert'}else spans[3].className='safe'}
function estimate(strategy){const pend=pendingOrders();if(!pend.length)return{distance:0,energy:0,ontime:null};let distance=0,energy=0,late=0;const vehicles=state.vehicles.map(v=>({...v})),queue=pend.slice();while(queue.length){const anchor=queue[0],candidateGroups=vehicles.map(v=>{let group=[anchor],qty=anchor.qty;if(strategy==='batch')for(const o of queue.slice(1))if(o.origin===anchor.origin&&o.dest===anchor.dest&&qty+o.qty<=v.capacity){group.push(o);qty+=o.qty}return{v,group,qty,c:qty<=v.capacity?vehicleCost(v,anchor,strategy):Infinity}}).filter(x=>Number.isFinite(x.c)).sort((a,b)=>a.c-b.c);if(!candidateGroups.length){late++;queue.shift();continue}const {v,group,qty}=candidateGroups[0],pickup=dijkstra(v.currentNode,anchor.origin),delivery=dijkstra(anchor.origin,anchor.dest);if(!Number.isFinite(pickup.distance+delivery.distance)){late+=group.length;group.forEach(o=>queue.splice(queue.indexOf(o),1));continue}const physicalKm=(pickup.physical+delivery.physical)*MAP_KM_PER_PIXEL,weightedKm=(pickup.distance+delivery.distance)*MAP_KM_PER_PIXEL,loadFactor=1+qty/v.capacity*.22;distance+=physicalKm;energy+=weightedKm*v.rate*loadFactor;const travel=pickup.distance/v.speed+delivery.distance/v.speed;if(state.time+travel>Math.min(...group.map(x=>x.due)))late+=group.length;v.currentNode=anchor.dest;group.forEach(o=>queue.splice(queue.indexOf(o),1))}return{distance,energy,ontime:Math.max(0,100-late/pend.length*100)}}
