function score(){if(state.metrics.delivered===0)return null;const total=Math.max(1,state.orders.length),rate=outcomeRate();if(rate===null)return null;const completion=Math.min(1,state.metrics.delivered/total),specific=state.metrics.distance?state.metrics.energy/state.metrics.distance:.22,energyEff=Math.max(0,Math.min(1,1-(specific-.052)/(.22-.052))),loaded=state.metrics.distance?state.metrics.loadedDistance/state.metrics.distance:0,safety=state.metrics.securityBlocked?Math.min(1,state.metrics.securityHandled/state.metrics.securityBlocked):1;const parts={ontime:rate/100*40,completion:completion*25,energy:energyEff*15,loaded:loaded*10,security:safety*10};return{value:Math.round(Object.values(parts).reduce((a,b)=>a+b,0)),parts}}
