function sceneTone(){const dawn=clamp01((state.time-390)/150),night=clamp01((state.time-1050)/150);return{night,ground:mixColor(mixColor('#cfdcb8','#c8e5c7',dawn),'#78938f',night),lawn:mixColor('#dcefc6','#8cac99',night),forest:mixColor('#68a982','#456e68',night),water:mixColor('#82d1df','#547c98',night),road:mixColor('#f5f3e9','#b9c4c5',night)}}
