function roadCurve(a,b){const p=nodes[a],q=nodes[b],dx=q.x-p.x,dy=q.y-p.y,len=Math.max(1,Math.hypot(dx,dy)),sign=(a.charCodeAt(0)+b.charCodeAt(b.length-1))%2?1:-1,bend=Math.min(7,len*.045)*sign;return{x:(p.x+q.x)/2-dy/len*bend,y:(p.y+q.y)/2+dx/len*bend}}
function traceRoad(a,b,ox=0,oy=0){const p=nodes[a],q=nodes[b],c=roadCurve(a,b);ctx.beginPath();ctx.moveTo(p.x+ox,p.y+oy);ctx.quadraticCurveTo(c.x+ox,c.y+oy,q.x+ox,q.y+oy)}
function drawRoads(now,tone){
 const primary=new Set(['01|02','02|13','05B|06','06|13','04|05R','04|09','09|10','13|14']);
 edgePairs.forEach(([a,b])=>{
  const main=primary.has(edgeKey(a,b)),closed=state.closed.has(edgeKey(a,b)),stone=mixColor('#d8d2c5','#9ba7a8',tone.night),curb=mixColor('#f5ead7','#c6cbca',tone.night);
  ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='rgba(47,67,66,.2)';ctx.lineWidth=main?24:18;traceRoad(a,b,3,4);ctx.stroke();
  ctx.strokeStyle=closed?'#f2a099':curb;ctx.lineWidth=main?21:15;traceRoad(a,b);ctx.stroke();
  ctx.strokeStyle=closed?'#ef756c':stone;ctx.lineWidth=main?16:11;traceRoad(a,b);ctx.stroke();
  // 细密短划模拟参考图中的浅色石材铺砖，而不是车道中心线。
  ctx.save();ctx.strokeStyle=closed?'rgba(132,42,38,.42)':'rgba(255,255,255,.42)';ctx.lineWidth=main?7:5;ctx.setLineDash([1,7]);traceRoad(a,b);ctx.stroke();ctx.restore();
  const tf=trafficFactor(a,b);ctx.strokeStyle=closed?'#9f322e':state.layers.traffic?(tf>1.35?'rgba(224,111,75,.82)':tf>1.15?'rgba(205,172,75,.72)':'rgba(112,139,137,.42)'):'rgba(112,139,137,.3)';ctx.lineWidth=2;traceRoad(a,b);ctx.stroke();
  if(state.running&&!closed){ctx.save();ctx.strokeStyle='rgba(255,255,255,.72)';ctx.lineWidth=2;ctx.setLineDash([3,20]);ctx.lineDashOffset=-(now*17)%23;traceRoad(a,b);ctx.stroke();ctx.restore()}
  if(closed){const p=nodes[a],q=nodes[b],c=roadCurve(a,b),x=(p.x+2*c.x+q.x)/4,y=(p.y+2*c.y+q.y)/4;ctx.fillStyle='#fff';ctx.font='800 18px sans-serif';ctx.textAlign='center';ctx.fillText('×',x,y+6)}
 })
}
