function renderStaticLayer(now,key){const liveCtx=ctx;ctx=staticCtx;ctx.clearRect(0,0,staticCanvas.width,staticCanvas.height);const tone=drawTerrain(now);drawRoads(now,tone);cachedBuildingMetrics={};Object.entries(nodes).forEach(([id,n])=>cachedBuildingMetrics[id]=drawBuilding(id,n));drawLamps(now,tone);ctx=liveCtx;staticKey=key}
function draw(){drawQueued=false;const now=performance.now()/1000,key=[Math.floor(state.time),[...state.closed].sort().join(','),state.layers.traffic,state.events.has('flood'),state.running,typeof loadedModels==='undefined'?0:loadedModels].join('|');if(key!==staticKey)renderStaticLayer(now,key);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(state.view.ox,state.view.oy);ctx.scale(state.view.scale,state.view.scale);ctx.drawImage(staticCanvas,0,0);const p=period(state.time);if(state.layers.mobility)Object.values(nodes).forEach(n=>{let x=['teach','dorm','hub','market'].includes(n.type)?p.mobility:.25;if(n.type==='sport'&&state.time>960)x=.55;drawHeat(n,x,'rgba(255,122,99,.25)')});if(state.layers.orders)pendingOrders().forEach(o=>drawHeat(nodes[o.dest],.55,'rgba(255,69,72,.42)'));state.vehicles.forEach(drawVehicleRoute);state.vehicles.forEach(drawVehicle);if(state.layers.labels)drawMapLabels(cachedBuildingMetrics);if(state.layers.security&&state.quarantine.some(o=>o.status==='quarantined')){ctx.fillStyle='#fb6e68';ctx.beginPath();ctx.arc(nodes['24'].x+35,nodes['24'].y-27,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font='800 13px sans-serif';ctx.textAlign='center';ctx.fillText('!',nodes['24'].x+35,nodes['24'].y-22)}ctx.restore();if(state.running||state.events.has('flood'))requestDraw()}
let toastTimer;
