const judgeThresholds=[0,5,16,27,38,49,66],judgeMessages=['场景：16:15启动，10个确定性订单、5辆车，目标是准时、低能耗与可信派单。','协同派单：5辆车分别获得任务，取货点、目的地和路径同步高亮。','正常配送：订单卡持续保留，并区分待派、取货中、配送中和已送达。','道路封闭：保留车辆在当前道路上的位置，比较前行与掉头后重新规划。','安全拦截：规范化JSON经SHA-256校验，摘要不一致订单先隔离、后人工复核。','高峰接力：生成后续订单，车辆完成上一单后自动接力，统计口径不丢单。','可信结算：至少6单实际完成后，按0–100分权重展示可解释结论。'];
function setDemoStage(step,text=''){state.demoStage=step;$$('[data-demo-step]').forEach(el=>{const n=+el.dataset.demoStep;el.classList.toggle('active',n===step);el.classList.toggle('done',step>n)});if(text)$('#judgeGuideText').textContent=text;['judgePrev','judgePause','judgeNext','judgeRestart','stopJudgeMode'].forEach(id=>{const el=$('#'+id);if(el)el.hidden=!state.judgeMode});$('#judgePrev').disabled=step<=1}
function judgeOrders(){const specs=[['06','05B',2,36,'快递'],['06','07',2,38,'快递'],['06','08',1,40,'餐饮'],['13','01',1,42,'商超'],['24','04',1,44,'场地运维'],['06','12',2,46,'快递'],['13','14',1,48,'商超'],['05R','23',1,52,'行政教学'],['06','17',1,54,'餐饮'],['13','09',1,56,'商超']];state.orders=[];specs.forEach((x,i)=>createOrder(x[0],x[1],x[2],x[3],i<2?'紧急':'普通',`J-${String(i+1).padStart(2,'0')}`,x[4]));state.orderWave=1;state.nextWaveMinute=state.sessionStart+10}
function startJudgeMode(){reset();state.orders=[];state.metrics={energy:0,distance:0,loadedDistance:0,delivered:0,ontime:0,late:0,securityBlocked:0,securityHandled:0,securityMissed:0};state.judgeMode=true;state.judgePaused=false;state.demoElapsed=0;state.speed=1;state.time=975;state.sessionStart=975;state.sessionEnd=1035;$('#speedSelect').value='1';judgeOrders();$('#log').innerHTML='';addLog('评委样例已加载：10个确定性订单、5辆车');state.judgeComparison={nearest:estimate('nearest'),eco:estimate('eco')};setDemoStage(1,judgeMessages[0]);state.running=true;$('#playBtn').textContent='Ⅱ 暂停';$('#judgeModeBtn').disabled=true;$('.map-card').scrollIntoView({behavior:'smooth',block:'start'});showToast('60–90秒确定性评委体验已启动。');renderAll()}
function stopJudgeMode(){clearJudgeTimers();state.judgeMode=false;state.judgePaused=false;state.running=false;$('#playBtn').textContent='▶ 开始仿真';$('#judgeModeBtn').disabled=false;setDemoStage(0,'演示已退出。可手动操作调度、事件和时间模型。');requestDraw()}
function runJudgeStage(step){if(step<=state.demoStage)return;setDemoStage(step,judgeMessages[step-1]);if(step===2){state.vehicles.forEach((v,i)=>assignOrders(v,[state.orders[i]]));state.running=true}if(step===3){autoDispatch()}if(step===4){const o=createOrder('06','07',1,35,'紧急','J-R1','道路应急');const v=state.vehicles.find(x=>x.status==='空闲');if(v)assignOrders(v,[o]);state.judgeTimers.push(setTimeout(()=>{if(state.judgeMode&&!state.events.has('closure'))triggerEvent('closure',$('[data-event="closure"]'))},900))}if(step===5&&!state.events.has('attack')){triggerEvent('attack',$('[data-event="attack"]')).then(()=>state.judgeTimers.push(setTimeout(()=>{if(state.judgeMode)reviewAttack()},3500)))}if(step===6){state.orderWave=6;for(const x of [['06','05B'],['06','12'],['13','08'],['13','15']])createOrder(x[0],x[1],1,28,'普通',null,'高峰接力');autoDispatch()}renderAll()}
function finishJudgeDemo(){const r=score();if(state.metrics.delivered<6||r===null)return false;setDemoStage(7,judgeMessages[6]);clearJudgeTimers();state.judgeMode=false;state.running=false;$('#judgeModeBtn').disabled=false;['judgePrev','judgePause','judgeNext','judgeRestart','stopJudgeMode'].forEach(id=>$('#'+id).hidden=true);settle();return true}
function advanceJudgeDemo(dt){if(!state.judgeMode||state.judgePaused)return;state.demoElapsed+=dt;for(let i=1;i<judgeThresholds.length;i++)if(state.demoElapsed>=judgeThresholds[i]&&state.demoStage<i+1)runJudgeStage(i+1);if(state.demoElapsed>=judgeThresholds[6]&&!finishJudgeDemo()&&state.demoElapsed>84){setDemoStage(7,'有效样本不足，演示继续运行而不生成虚假等级；请等待实际完成6单。')}}
