function runExperimentSuite(){const saved={time:state.time,orders:state.orders,vehicles:state.vehicles,events:state.events,closed:state.closed};const scenarios=[{name:'常态16:15',time:975,extra:false,events:[],closed:[]},{name:'取件高峰17:00',time:1020,extra:true,events:['surge'],closed:[]},{name:'06-07道路封闭',time:975,extra:false,events:['closure'],closed:[edgeKey('06','07')]}],strategies=[['nearest','就近优先'],['batch','批量优先'],['eco','综合优化']],rows=[];try{for(const scenario of scenarios){state.time=scenario.time;state.orders=experimentOrders(scenario.extra);state.vehicles=[makeVehicle('E-01','van','06'),makeVehicle('E-02','van','06'),makeVehicle('U-01','bot','06'),makeVehicle('U-02','bot','13'),makeVehicle('U-03','bot','06')];state.events=new Set(scenario.events);state.closed=new Set(scenario.closed);for(const [key,label] of strategies){const r=estimate(key);rows.push({scenario:scenario.name,strategy:label,distance:r.distance,energy:r.energy,ontime:r.ontime})}}}finally{state.time=saved.time;state.orders=saved.orders;state.vehicles=saved.vehicles;state.events=saved.events;state.closed=saved.closed}state.experimentRows=rows;$('#experimentSummary').innerHTML='<table class="experiment-table"><thead><tr><th>情景</th><th>策略</th><th>预测里程</th><th>预测能耗</th><th>准时率</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${r.scenario}</td><td>${r.strategy}</td><td class="num">${r.distance.toFixed(2)} km</td><td class="num">${r.energy.toFixed(2)} kWh</td><td class="num">${r.ontime.toFixed(0)}%</td></tr>`).join('')+'</tbody></table>';$('#exportExperiments').disabled=false;addLog('已完成三情景、三策略敏感性测算');showToast('9组可复核结果已生成，可导出CSV。')}
function exportExperiments(){if(!state.experimentRows.length)return;const lines=['情景,策略,预测里程(km),预测能耗(kWh),准时率(%)',...state.experimentRows.map(r=>[r.scenario,r.strategy,r.distance.toFixed(3),r.energy.toFixed(3),r.ontime.toFixed(1)].join(','))];const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='智行校园-三情景策略测算.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('测算结果已导出。')}
