function tick(now){if(!tick.last)tick.last=now;const dt=Math.min(.1,(now-tick.last)/1000);tick.last=now;if(state.running&&state.time<state.sessionEnd){const simMin=dt*state.speed;state.time=Math.min(state.sessionEnd,state.time+simMin);state.vehicles.forEach(v=>updateVehicle(v,simMin));requestDraw();if(state.time>=state.sessionEnd&&!state.judgeMode){state.flowComplete=true;addLog(`到达一小时结算点 ${fmtTime(state.sessionEnd)}`);settle()}else{if(!state.judgeMode&&state.orderWave<state.maxOrderWaves&&state.time>=state.nextWaveMinute)generateOrderWave();if((!state.judgeMode||state.demoStage>=2)&&pendingOrders().length&&state.vehicles.some(v=>v.status==='空闲'&&v.battery>=16))autoDispatch();if(Math.floor(state.time)%2===0)renderAll()}}advanceJudgeDemo(dt);requestAnimationFrame(tick)}
function settle(){state.running=false;state.activityStarted=true;$('#playBtn').textContent='▶ 开始仿真';const delivered=state.metrics.delivered,rate=outcomeRate(),empty=state.metrics.distance?100*(1-state.metrics.loadedDistance/state.metrics.distance):null,overdue=overdueOrders().length,result=score();if(result===null){$('#resultScore').textContent='—';$('#resultTitle').textContent='尚未形成有效结算样本';$('#resultBreakdown').innerHTML='<div>完成订单<b>0</b></div><div>准时率<b>待形成样本</b></div><div>评分状态<b>不生成等级</b></div><div>处理建议<b>先完成至少1单</b></div>'}else{const p=result.parts,comparison=state.judgeComparison,distGain=comparison&&comparison.nearest.distance?100*(comparison.nearest.distance-comparison.eco.distance)/comparison.nearest.distance:null,energyGain=comparison&&comparison.nearest.energy?100*(comparison.nearest.energy-comparison.eco.energy)/comparison.nearest.energy:null;$('#resultScore').textContent=result.value;$('#resultTitle').textContent=result.value>=85?'优秀：调度稳定且证据完整':result.value>=70?'良好：仍有优化空间':'需要调整调度策略';$('#resultBreakdown').innerHTML=`<div>完成订单<b>${delivered}</b></div><div>准时率<b>${rate.toFixed(0)}%</b></div><div>累计里程<b>${state.metrics.distance.toFixed(2)} km</b></div><div>累计能耗<b>${state.metrics.energy.toFixed(2)} kWh</b></div><div>空驶率<b>${empty===null?'--':empty.toFixed(0)+'%'}</b></div><div>安全复核<b>${state.metrics.securityHandled}/${state.metrics.securityBlocked}</b></div><div>准时 / 完成分<b>${p.ontime.toFixed(1)} / ${p.completion.toFixed(1)}</b></div><div>能效 / 载程 / 安全分<b>${p.energy.toFixed(1)} / ${p.loaded.toFixed(1)} / ${p.security.toFixed(1)}</b></div>${distGain!==null?`<div class="result-conclusion">同引擎预测：综合优化较就近优先里程${distGain>=0?'减少':'增加'} ${Math.abs(distGain).toFixed(1)}%，能耗${energyGain>=0?'降低':'增加'} ${Math.abs(energyGain).toFixed(1)}%。本局${state.orders.length}单中${delivered}单完成，${state.metrics.ontime}单准时。</div>`:''}`};renderPanels();requestDraw();$('#resultDialog').showModal()}
$('#judgeModeBtn').onclick=startJudgeMode;$('#stopJudgeMode').onclick=stopJudgeMode;$('#judgeRestart').onclick=startJudgeMode;$('#judgePause').onclick=()=>{state.judgePaused=!state.judgePaused;state.running=!state.judgePaused;$('#judgePause').textContent=state.judgePaused?'继续':'暂停';showToast(state.judgePaused?'评委演示已暂停。':'评委演示继续。')};$('#judgeNext').onclick=()=>{const next=Math.min(7,state.demoStage+1);state.demoElapsed=Math.max(state.demoElapsed,judgeThresholds[next-1]||0);if(next===7)finishJudgeDemo();else runJudgeStage(next)};$('#judgePrev').onclick=()=>{const prev=Math.max(1,state.demoStage-1);setDemoStage(prev,judgeMessages[prev-1]+'（仅回看说明，车辆状态不回滚）')};$('#playBtn').onclick=toggleSimulation;$('#speedSelect').onchange=e=>state.speed=+e.target.value;$('#resetBtn').onclick=reset;$('#settleBtn').onclick=settle;$('#closeResult').onclick=()=>$('#resultDialog').close();$('#autoDispatch').onclick=autoDispatch;$('#refreshCompare').onclick=()=>{renderCompare();addLog('已按当前路况重新测算三种策略')};$('#reviewAttack').onclick=reviewAttack;$('#clearLog').onclick=()=>$('#log').innerHTML='';$('#runExperiments').onclick=runExperimentSuite;$('#exportExperiments').onclick=exportExperiments;$('#exportValidation').onclick=exportValidation;
