canvas.addEventListener('wheel',e=>{e.preventDefault();state.view.scale=Math.max(.75,Math.min(1.7,state.view.scale*(e.deltaY<0?1.08:.92)));requestDraw()},{passive:false});canvas.addEventListener('pointerdown',e=>{state.drag={x:e.clientX,y:e.clientY,ox:state.view.ox,oy:state.view.oy,moved:false};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging')});canvas.addEventListener('pointermove',e=>{if(!state.drag)return;const dx=e.clientX-state.drag.x,dy=e.clientY-state.drag.y;if(Math.hypot(dx,dy)>3)state.drag.moved=true;state.view.ox=state.drag.ox+dx*(canvas.width/canvas.clientWidth);state.view.oy=state.drag.oy+dy*(canvas.height/canvas.clientHeight);requestDraw()});canvas.addEventListener('pointerup',e=>{if(state.drag&&!state.drag.moved){const r=canvas.getBoundingClientRect(),x=((e.clientX-r.left)*canvas.width/r.width-state.view.ox)/state.view.scale,y=((e.clientY-r.top)*canvas.height/r.height-state.view.oy)/state.view.scale;let hit=null,best=40;Object.entries(nodes).forEach(([id,n])=>{const d=Math.hypot(x-n.x,y-n.y);if(d<best){best=d;hit=[id,n]}});if(hit){const model=hit[1].model?` · ${hit[1].model}`:'';$('#mapTip').textContent=`${hit[0]==='05R'?'05行政':hit[0]==='05B'?'05女寝':hit[0]} ${hit[1].name} · ${typeLabels[hit[1].type]}${model} · ${hit[1].note}`}}state.drag=null;canvas.classList.remove('dragging');requestDraw()});
